try:
    print('>>> x = range(0)')
    print('>>> y = {}')
    print('>>> x += y')
    print('>>> x')
    x = range(0)
    y = {}
    x += y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
##################################################
try:
    print('>>> x = range(0)')
    print('>>> y = {"a": 1, "c": 2.3456, "d": "another"}')
    print('>>> x += y')
    print('>>> x')
    x = range(0)
    y = {"a": 1, "c": 2.3456, "d": "another"}
    x += y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
